package com.example.rokidgeminisecretary;
import android.content.*;import org.json.*;import java.io.*;import java.util.*;
final class ConversationReliability {
 private static final LinkedHashMap<String,JSONObject> partials=new LinkedHashMap<>();
 static synchronized void partial(String id,String state,JSONObject data,long now)throws Exception{
  if(!TrackedWebRequest.validId(id))throw new IOException("依頼IDが不正です");
  if(!state.equals("RUNNING")){partials.remove(id);return;}if(!data.has("partial"))return;
  String text=data.getString("partial");long seq=data.getLong("partialSequence");if(text.length()>12000||seq<0)throw new IOException("途中表示の上限です");JSONObject old=partials.get(id);if(old!=null&&seq<=old.getLong("sequence"))return;
  partials.put(id,new JSONObject().put("requestId",id).put("text",text).put("sequence",seq).put("updatedAt",now));while(partials.size()>4)partials.remove(partials.keySet().iterator().next());
 }
 static synchronized JSONArray partials(JSONArray ledger,long now)throws Exception{JSONArray out=new JSONArray();HashSet<String> active=new HashSet<>();for(int i=0;i<ledger.length();i++){JSONObject row=ledger.getJSONObject(i);if(row.optString("requestState").equals("RUNNING"))active.add(row.optString("key"));}Iterator<Map.Entry<String,JSONObject>> it=partials.entrySet().iterator();while(it.hasNext()){Map.Entry<String,JSONObject> item=it.next();if(!active.contains(item.getKey())||now-item.getValue().getLong("updatedAt")>120000||now<item.getValue().getLong("updatedAt")){it.remove();continue;}out.put(new JSONObject(item.getValue().toString()));}return out;}
 static JSONObject settings(Context c)throws Exception{SharedPreferences p=c.getSharedPreferences("conversation-display",0);return new JSONObject().put("answerStyle",p.getString("answerStyle","short")).put("glassChars",p.getInt("glassChars",600)).put("streaming",p.getBoolean("streaming",true));}
 static JSONObject settings(Context c,JSONObject input)throws Exception{String style=input.getString("answerStyle");int chars=input.getInt("glassChars");if(!style.matches("short|detailed")||!(chars==300||chars==600||chars==1200))throw new IOException("表示設定を確認してください");if(!c.getSharedPreferences("conversation-display",0).edit().putString("answerStyle",style).putInt("glassChars",chars).putBoolean("streaming",input.getBoolean("streaming")).commit())throw new IOException("設定を保存できません");return settings(c);}
 static String failure(String reason){switch(reason){case "NETWORK":return "通信を完了できませんでした。接続と履歴を確認し、必要なら入力欄へ戻してください。自動再送はしません。";case "RATE_LIMIT":return "APIが混雑または利用上限です。待ってから履歴を確認してください。";case "AUTH":return "APIの認証・利用条件を確認してください。";case "MODEL_ERROR":return "モデルの回答処理に失敗しました。操作の成否と履歴を確認してください。";case "SAFETY_STOP":return "安全判定で停止しました。依頼内容を見直してください。";case "REFERENCE_CHANGED":return "参照画像が変わりました。選び直してください。";case "RESTART":case "INTERRUPTED":return "結果が未確認です。履歴を確認してから再依頼を判断してください。";default:return "履歴と依頼の状態を確認してください。";}}
 static JSONObject reconcile(Context c)throws Exception{synchronized(LokiWebConsole.class){JSONArray all=ConversationContinuation.ledger(c),rows=new JSONArray();boolean changed=false;for(int i=0;i<all.length();i++){JSONObject row=all.getJSONObject(i);if(!row.optBoolean("tracked")||TrackedWebRequest.terminal(row.optString("requestState")))continue;boolean inQueue=MainActivity.hasQueuedWebCommand(c,row.optString("key"));if(row.optString("requestState").matches("CREATED|QUEUED")&&!inQueue){row.put("requestState","UNCONFIRMED").put("receiptReason","RESTART").put("finishedAt",System.currentTimeMillis());changed=true;}rows.put(new JSONObject().put("key",row.optString("key")).put("state",row.optString("requestState")).put("inPhoneQueue",inQueue));}if(changed&&!c.getSharedPreferences("loki_web_console",0).edit().putString("outbox",all.toString()).commit())throw new IOException("復旧状態を保存できません");return new JSONObject().put("items",rows).put("automaticallyResent",false).put("note","保存済みの待ち行列と照合しました。受信済みの依頼はメガネからの確認を待ちます。自動で新規送信しません。");}}
 static JSONObject page(JSONArray history,int limit,String before,String revision)throws Exception{JSONArray groups=ConversationCollections.group(history);String hash=RecorderPhotoStore.hash(groups.toString().getBytes("UTF-8"));if(limit<1||limit>40)throw new IOException("読み込み件数が不正です");int end=groups.length();if(!before.isEmpty()){if(!hash.equals(revision))throw new IOException("履歴が更新されました。最新を読み直してください");end=-1;for(int i=0;i<groups.length();i++)if(groups.getJSONObject(i).getString("key").equals(before))end=i;if(end<0)throw new IOException("読み込み位置が変わりました");}int start=Math.max(0,end-limit);JSONArray items=new JSONArray();for(int i=start;i<end;i++){JSONArray rows=groups.getJSONObject(i).getJSONArray("rows");for(int j=0;j<rows.length();j++)items.put(rows.get(j));}return new JSONObject().put("items",items).put("revision",hash).put("hasMore",start>0).put("before",start<end?groups.getJSONObject(start).getString("key"):"");}
 static long size(File file,int depth)throws Exception{if(!file.exists())return 0;if(depth<0)throw new IOException("保存階層の上限です");if(file.isFile())return file.length();long bytes=0;File[] children=file.listFiles();if(children==null)throw new IOException("保存量を取得できません");for(File child:children){if(!child.getCanonicalFile().getParentFile().equals(file.getCanonicalFile()))throw new IOException("保存範囲外です");bytes+=size(child,depth-1);}return bytes;}
 static JSONObject storage(MainActivity c)throws Exception{return new JSONObject().put("conversationBytes",c.webConversationBytes()).put("photoBytes",size(RecorderPhotoStore.root(c),3)).put("favoriteBytes",size(ConversationWorkspace.file(c,"reliability-conversation-favorites").getBaseFile(),0)).put("favoriteCount",ConversationCollections.favorites(c).length()).put("freeBytes",c.getFilesDir().getUsableSpace()).put("scope","スマホ内の共有会話（アーカイブ含む）・受信写真・お気に入り。生成画像・動画・端末全体の使用量は含みません。");}
 static JSONObject diagnostics(MainActivity c)throws Exception{JSONArray ledger=ConversationContinuation.ledger(c);JSONObject counts=new JSONObject(),reasons=new JSONObject();for(int i=0;i<ledger.length();i++){String state=ledger.getJSONObject(i).optString("requestState");if(state.matches("CREATED|QUEUED|RECEIVED|RUNNING|ANSWERED|FAILED|UNCONFIRMED|STOPPED|CANCELLED|SUPERSEDED"))counts.put(state,counts.optInt(state)+1);String reason=ledger.getJSONObject(i).optString("receiptReason");if(reason.matches("NETWORK|RATE_LIMIT|AUTH|MODEL_ERROR|SAFETY_STOP|INTERRUPTED|LOCAL_RESULT|RESTART|REFERENCE_CHANGED"))reasons.put(reason,reasons.optInt(reason)+1);}JSONObject runtime=c.webConversationRuntime();return new JSONObject().put("schema",1).put("phoneVersion",251).put("requestStateCounts",counts).put("receiptReasonCounts",reasons).put("glassContactRecent",runtime.optBoolean("contactRecent")).put("settings",settings(c)).put("timing",ConversationContinuation.timing(ledger,System.currentTimeMillis())).put("excluded","会話本文・画像・依頼ID・端末名・接続先・認証情報・例外詳細は含みません");}
 private ConversationReliability(){}
}
